CREATE OR REPLACE FUNCTION private.assert_assignment_question_body_v1(q assignment_questions)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare failures text[]; begin if q.prompt is null or q.choices is null then raise exception 'question_body_not_null' using errcode='23502'; end if;
      select array_remove(array[case when ((base_order_index > 0)) is false then 'assignment_questions_base_order_index_check'::text end,case when (((canonical_content_hash_snapshot IS NULL) OR (canonical_content_hash_snapshot ~ '^[0-9A-Fa-f]{64}$'::text))) is false then 'assignment_questions_canonical_hash_check'::text end,case when (((canonical_question_item_sha256_snapshot IS NULL) OR (canonical_question_item_sha256_snapshot ~ '^[0-9a-f]{64}$'::text))) is false then 'assignment_questions_canonical_item_sha_check'::text end,case when ((((provenance_status = 'preview_verified_v1'::text) AND (direction = 'korean_to_english'::public.question_direction) AND (eligibility_quiz_mode = ANY (ARRAY['canonical_definition_to_headword'::text, 'canonical_example_to_headword'::text])) AND (content_origin = 'canonical'::text) AND (cardinality(choice_vocab_entry_ids) = 4) AND (array_position(choice_vocab_entry_ids, NULL::bigint) IS NULL) AND (cardinality(array_positions(choice_vocab_entry_ids, vocab_entry_id)) = 1) AND (choice_vocab_entry_ids[(correct_choice_index + 1)] = vocab_entry_id) AND (correct_answer_snapshot = (choices ->> (correct_choice_index)::integer)) AND (canonical_question_release_id_snapshot IS NOT NULL) AND (canonical_question_item_id_snapshot IS NOT NULL) AND (canonical_question_item_sha256_snapshot IS NOT NULL) AND (canonical_question_review_input_sha256_snapshot IS NOT NULL) AND (canonical_question_review_policy_version_snapshot IS NOT NULL) AND (generator_version_snapshot = 'canonical-question-preview-v1'::text)) OR ((provenance_status <> 'preview_verified_v1'::text) AND (canonical_question_release_id_snapshot IS NULL) AND (canonical_question_item_id_snapshot IS NULL) AND (canonical_question_item_sha256_snapshot IS NULL) AND (canonical_question_review_input_sha256_snapshot IS NULL) AND (canonical_question_review_policy_version_snapshot IS NULL)))) is false then 'assignment_questions_canonical_preview_v1_check'::text end,case when (((canonical_question_review_input_sha256_snapshot IS NULL) OR (canonical_question_review_input_sha256_snapshot ~ '^[0-9a-f]{64}$'::text))) is false then 'assignment_questions_canonical_review_sha_check'::text end,case when (((jsonb_typeof(choices) = 'array'::text) AND (jsonb_array_length(choices) = 4))) is false then 'assignment_questions_choices_check'::text end,case when ((((provenance_status <> 'composition_verified_v1'::text) AND (composition_version_id_snapshot IS NULL) AND (composition_item_id_snapshot IS NULL) AND (composition_item_sha256_snapshot IS NULL) AND (composition_pronunciation_snapshot IS NULL)) OR COALESCE(((provenance_status = 'composition_verified_v1'::text) AND (composition_version_id_snapshot IS NOT NULL) AND (composition_item_id_snapshot IS NOT NULL) AND (composition_item_sha256_snapshot IS NOT NULL) AND (jsonb_typeof(composition_pronunciation_snapshot) = 'object'::text) AND (jsonb_typeof((composition_pronunciation_snapshot -> 'target'::text)) = 'object'::text) AND (jsonb_typeof((composition_pronunciation_snapshot -> 'choices'::text)) = 'array'::text) AND (jsonb_array_length((composition_pronunciation_snapshot -> 'choices'::text)) = 4) AND (dataset_id IS NOT NULL) AND (entry_row_sha256_snapshot IS NOT NULL) AND (headword_snapshot IS NOT NULL) AND (primary_meaning_snapshot IS NOT NULL) AND (question_content_sha256 IS NOT NULL) AND (generator_version_snapshot = 'vocabulary-composition-bank-v1'::text) AND (content_origin = 'book_occurrence'::text) AND (canonical_lexeme_id_snapshot IS NULL) AND (canonical_question_release_id_snapshot IS NULL) AND (reviewed_exam_release_id_snapshot IS NULL) AND (cardinality(choice_vocab_entry_ids) = 4) AND (array_position(choice_vocab_entry_ids, NULL::bigint) IS NULL) AND (cardinality(array_positions(choice_vocab_entry_ids, vocab_entry_id)) = 1) AND (choice_vocab_entry_ids[(correct_choice_index + 1)] = vocab_entry_id) AND (correct_answer_snapshot = (choices ->> (correct_choice_index)::integer)) AND (((eligibility_quiz_mode = ANY (ARRAY['book_meaning_en_to_ko'::text, 'canonical_headword_to_definition'::text])) AND (direction = 'english_to_korean'::public.question_direction)) OR ((eligibility_quiz_mode = ANY (ARRAY['book_meaning_ko_to_en'::text, 'canonical_definition_to_headword'::text])) AND (direction = 'korean_to_english'::public.question_direction)))), false))) is false then 'assignment_questions_composition_v1_check'::text end,case when (((question_content_sha256 IS NULL) OR (question_content_sha256 ~ '^[0-9A-F]{64}$'::text))) is false then 'assignment_questions_content_hash_check'::text end,case when (((content_origin IS NULL) OR (content_origin = ANY (ARRAY['book_occurrence'::text, 'canonical'::text])))) is false then 'assignment_questions_content_origin_check'::text end,case when (((correct_choice_index >= 0) AND (correct_choice_index <= 3))) is false then 'assignment_questions_correct_choice_index_check'::text end,case when (((eligibility_input_hash_snapshot IS NULL) OR (eligibility_input_hash_snapshot ~ '^[0-9A-F]{64}$'::text))) is false then 'assignment_questions_eligibility_hash_check'::text end,case when (((eligibility_quiz_mode IS NULL) OR (eligibility_quiz_mode = ANY (ARRAY['book_meaning_en_to_ko'::text, 'book_meaning_ko_to_en'::text, 'canonical_definition_to_headword'::text, 'canonical_example_to_headword'::text, 'canonical_headword_to_definition'::text])))) is false then 'assignment_questions_eligibility_mode_check'::text end,case when (((entry_row_sha256_snapshot IS NULL) OR (entry_row_sha256_snapshot ~ '^[0-9A-F]{64}$'::text))) is false then 'assignment_questions_entry_sha_check'::text end,case when ((((provenance_status <> 'notebook_snapshot_v1'::text) AND (notebook_source_event_id IS NULL) AND (notebook_source_snapshot IS NULL) AND (notebook_pronunciation_snapshot IS NULL)) OR COALESCE(((provenance_status = 'notebook_snapshot_v1'::text) AND (notebook_source_event_id IS NOT NULL) AND (jsonb_typeof(notebook_source_snapshot) = 'object'::text) AND (jsonb_typeof(notebook_pronunciation_snapshot) = 'object'::text) AND (jsonb_typeof((notebook_pronunciation_snapshot -> 'target'::text)) = 'object'::text) AND (jsonb_typeof((notebook_pronunciation_snapshot -> 'choices'::text)) = 'array'::text) AND (jsonb_array_length((notebook_pronunciation_snapshot -> 'choices'::text)) = 4) AND (dataset_id IS NOT NULL) AND (headword_snapshot IS NOT NULL) AND (primary_meaning_snapshot IS NOT NULL) AND (generator_version_snapshot = 'notebook-bank-v1'::text) AND (question_content_sha256 IS NOT NULL) AND (cardinality(choice_vocab_entry_ids) = 4) AND (array_position(choice_vocab_entry_ids, NULL::bigint) IS NULL) AND (choice_vocab_entry_ids[(correct_choice_index + 1)] = vocab_entry_id) AND (correct_answer_snapshot = (choices ->> (correct_choice_index)::integer))), false))) is false then 'assignment_questions_notebook_proof'::text end,case when ((char_length(TRIM(BOTH FROM prompt)) > 0)) is false then 'assignment_questions_prompt_check'::text end,case when (((provenance_status = 'notebook_snapshot_v1'::text) OR ((provenance_status = 'composition_verified_v1'::text) OR (provenance_status = ANY (ARRAY['legacy_backfill'::text, 'verified_v2'::text, 'preview_verified_v1'::text, 'exam_reviewed_v1'::text]))))) is false then 'assignment_questions_provenance_status_check'::text end,case when ((((provenance_status <> 'exam_reviewed_v1'::text) AND (reviewed_exam_release_id_snapshot IS NULL) AND (reviewed_exam_item_id_snapshot IS NULL) AND (reviewed_exam_item_sha256_snapshot IS NULL)) OR COALESCE(((provenance_status = 'exam_reviewed_v1'::text) AND (reviewed_exam_release_id_snapshot IS NOT NULL) AND (reviewed_exam_item_id_snapshot IS NOT NULL) AND (reviewed_exam_item_sha256_snapshot IS NOT NULL) AND (dataset_id IS NOT NULL) AND (entry_row_sha256_snapshot IS NOT NULL) AND (headword_snapshot IS NOT NULL) AND (primary_meaning_snapshot IS NOT NULL) AND (question_content_sha256 IS NOT NULL) AND (generator_version_snapshot = 'reviewed-exam-bank-v1'::text) AND (content_origin = 'book_occurrence'::text) AND (cardinality(choice_vocab_entry_ids) = 4) AND (array_position(choice_vocab_entry_ids, NULL::bigint) IS NULL) AND (cardinality(array_positions(choice_vocab_entry_ids, vocab_entry_id)) = 1) AND (choice_vocab_entry_ids[(correct_choice_index + 1)] = vocab_entry_id) AND (correct_answer_snapshot = (choices ->> (correct_choice_index)::integer)) AND (((eligibility_quiz_mode = ANY (ARRAY['book_meaning_en_to_ko'::text, 'canonical_headword_to_definition'::text])) AND (direction = 'english_to_korean'::public.question_direction)) OR ((eligibility_quiz_mode = ANY (ARRAY['book_meaning_ko_to_en'::text, 'canonical_definition_to_headword'::text])) AND (direction = 'korean_to_english'::public.question_direction)))), false))) is false then 'assignment_questions_reviewed_exam_v1_check'::text end,case when (((provenance_status <> 'verified_v2'::text) OR COALESCE(((dataset_id IS NOT NULL) AND (entry_row_sha256_snapshot IS NOT NULL) AND (eligibility_quiz_mode IS NOT NULL) AND (eligibility_input_hash_snapshot IS NOT NULL) AND (headword_snapshot IS NOT NULL) AND (headword_normalized_snapshot IS NOT NULL) AND (primary_meaning_snapshot IS NOT NULL) AND (choice_vocab_entry_ids IS NOT NULL) AND (cardinality(choice_vocab_entry_ids) = 4) AND (correct_answer_snapshot IS NOT NULL) AND (correct_answer_snapshot = (choices ->> (correct_choice_index)::integer)) AND (content_origin IS NOT NULL) AND (content_origin = 'book_occurrence'::text) AND (eligibility_rule_version_snapshot IS NOT NULL) AND (generator_version_snapshot IS NOT NULL) AND (question_content_sha256 IS NOT NULL) AND (provenance IS NOT NULL) AND (jsonb_typeof(provenance) = 'object'::text)), false))) is false then 'assignment_questions_verified_v2_check'::text end],null::text) into failures from (select (q).*) original_row;
      if q.generator_version_snapshot='notebook-bank-v2' then perform private.assert_notebook_origin_v2(q); failures:=array_remove(failures,'assignment_questions_notebook_proof'); end if;
      if cardinality(failures)>0 then raise exception 'question_body_constraint_violation: %',failures[1] using errcode='23514',constraint=failures[1]; end if; end;$function$

CREATE OR REPLACE FUNCTION private.freeze_assignment_question_content_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare resolved public.assignment_questions; fields text[]:=array['prompt','choices','headword_snapshot','primary_meaning_snapshot',
  'correct_answer_snapshot','composition_pronunciation_snapshot','notebook_pronunciation_snapshot'];
begin

  if tg_op='UPDATE' and private.consume_historical_question_permit_v1(tg_relid,to_jsonb(old),to_jsonb(new)) then
    if new.content_version_id is null or (old.content_version_id is not null and old.content_version_id<>new.content_version_id)
      then raise exception 'historical_question_reference_changed' using errcode='23514'; end if;
    if exists(select 1 from jsonb_each(private.historical_question_document_v1('assignment',to_jsonb(new))->'body') e
      where e.value<>'null'::jsonb and e.value is distinct from
        (private.historical_question_document_v1('assignment',private.historical_question_resolve_v1('assignment',to_jsonb(new)))->'body')->e.key)
      then raise exception 'historical_question_body_mismatch' using errcode='23514'; end if;
    return new;
  end if;
  if tg_op='UPDATE' and old.content_version_id is not null and to_jsonb(new) is distinct from to_jsonb(old)
    then raise exception 'question_content_reference_immutable' using errcode='55000'; end if;
  if new.content_version_id is null and tg_op='INSERT' and new.provenance_status='notebook_snapshot_v1' then
    -- Prior choice and private-source triggers have already run on the full row.
    perform private.assert_assignment_question_body_v1(new);
    new.content_version_id:=case when new.generator_version_snapshot='notebook-bank-v2' then private.register_notebook_question_content_v2(new) else private.register_assignment_question_content_v1(new) end;
  end if;
  if new.content_version_id is null then perform private.assert_assignment_question_body_v1(new); return new; end if;
  resolved:=private.resolve_assignment_question_content_v1(new);
  if new.provenance_status<>'notebook_snapshot_v1' then fields:=array_append(fields,'provenance'); end if;
  if exists(select 1 from jsonb_each(private.vocabulary_question_json_fields_v1(to_jsonb(new),fields)) e
    where e.value<>'null'::jsonb and e.value is distinct from to_jsonb(resolved)->e.key)
    then raise exception 'question_content_body_mismatch' using errcode='23514'; end if;
  perform private.assert_assignment_question_body_v1(resolved);
  new.prompt:=null; new.choices:=null; new.headword_snapshot:=null; new.primary_meaning_snapshot:=null;
  new.correct_answer_snapshot:=null; new.composition_pronunciation_snapshot:=null; new.notebook_pronunciation_snapshot:=null;
  if new.provenance_status='notebook_snapshot_v1' then new.notebook_source_snapshot:=new.notebook_source_snapshot-'study';
  else new.provenance:=null; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.register_assignment_question_content_v1(q assignment_questions)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare binding jsonb; payload jsonb; bank jsonb; source_sha text; keys text[]; study jsonb;
begin
  binding:=private.vocabulary_question_binding_v1(q);
  payload:=private.vocabulary_question_json_fields_v1(to_jsonb(q),array['prompt','choices','headword_snapshot','primary_meaning_snapshot',
    'correct_answer_snapshot','composition_pronunciation_snapshot','notebook_pronunciation_snapshot']);
  if q.provenance_status='notebook_snapshot_v1' then
    study:=q.notebook_source_snapshot->'study';
    if study is not null and (jsonb_typeof(study) is distinct from 'object' or study-array[
      'entryId','currentHeadword','snapshotDisplayKo','dictionaryId','releaseId','displayKo','pronunciationSnapshot',
      'compositionPronunciation','notebookPronunciation','definition','example','exampleKo']<>'{}'::jsonb)
      then raise exception 'question_content_study_invalid' using errcode='22023'; end if;
    payload:=payload||jsonb_build_object('notebook_study',study);
  else payload:=payload||jsonb_build_object('provenance',q.provenance); end if;
  bank:=private.vocabulary_question_bank_body_v1(binding);
  if bank is not null then
    if exists(select 1 from jsonb_each(bank) e where payload->e.key is distinct from e.value)
      then raise exception 'question_content_source_mismatch' using errcode='23514'; end if;
    select array_agg(k) into keys from jsonb_object_keys(bank) k;
    payload:=payload-keys;
    source_sha:=encode(extensions.digest(bank::text,'sha256'),'hex');
  end if;
  return private.register_vocabulary_question_content_v1('assignment',
    private.vocabulary_question_scope_v1(array[q.vocab_entry_id]||coalesce(q.choice_vocab_entry_ids,'{}'::bigint[])),binding,payload,source_sha);
end;
$function$

CREATE OR REPLACE FUNCTION private.resolve_assignment_question_content_v1(q assignment_questions)
 RETURNS assignment_questions
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare material private.vocabulary_question_content_versions; payload jsonb; result public.assignment_questions;
begin
  q:=private.resolve_composition_assignment_hashes_v1(q);
  if q.content_version_id is null then return q; end if;
  select * into material from private.vocabulary_question_content_versions where id=q.content_version_id;
  if material.id is null or material.kind<>'assignment' or material.binding is distinct from private.vocabulary_question_binding_v1(q)
    then raise exception 'question_content_binding_mismatch' using errcode='55000'; end if;
  payload:=private.vocabulary_question_content_payload_v1(material);
  result:=jsonb_populate_record(q,payload-'notebook_study');
  if q.provenance_status='notebook_snapshot_v1' then
    result.notebook_source_snapshot:=q.notebook_source_snapshot||jsonb_build_object('study',payload->'notebook_study');
  end if;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.resolve_quiz_question_content_v1(q quiz_questions)
 RETURNS quiz_questions
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare material private.vocabulary_question_content_versions; payload jsonb; bank public.assignment_questions;
begin
  if q.content_version_id is null then return q; end if;
  select * into material from private.vocabulary_question_content_versions where id=q.content_version_id;
  if material.id is null or material.kind not in ('assignment','standalone')
    or material.binding->>'vocab_entry_id' is distinct from q.vocab_entry_id::text
    or material.binding->>'direction' is distinct from q.direction::text
    or material.binding->>'correct_choice_index' is distinct from q.correct_choice_index::text
    then raise exception 'question_content_binding_mismatch' using errcode='55000'; end if;
  if q.assignment_question_id is not null then
    select * into bank from public.assignment_questions where id=q.assignment_question_id;
    bank:=private.resolve_composition_assignment_hashes_v1(bank);
    if bank.id is null or (bank.content_version_id is not null and bank.content_version_id is distinct from q.content_version_id)
      or material.kind<>'assignment' or material.binding is distinct from private.vocabulary_question_binding_v1(bank)
      then raise exception 'question_content_assignment_mismatch' using errcode='55000'; end if;
  elsif material.kind<>'standalone' then raise exception 'question_content_assignment_mismatch' using errcode='55000'; end if;
  payload:=private.vocabulary_question_content_payload_v1(material);
  q.prompt:=payload->>'prompt'; q.choices:=payload->'choices';
  if q.prompt is null or jsonb_typeof(q.choices) is distinct from 'array' or jsonb_array_length(q.choices)<>4
    then raise exception 'question_content_unavailable' using errcode='55000'; end if;
  return q;
end;
$function$
